import {
  afterAll,
  afterEach,
  beforeEach,
  describe,
  expect,
  spyOn,
  test,
} from "bun:test";
import { PERSONAS } from "./personas";
import * as aiClient from "./ai-client";
import * as orchestrator from "./ai-orchestrator";
import { setBrowserTtsCapabilityOverride } from "./browser-inference";
import { lockBrowserGlobalsForTestFile } from "./test-browser-globals-lock";

const releaseBrowserGlobalsLock = await lockBrowserGlobalsForTestFile();
const browserGlobalNames = [
  "window",
  "localStorage",
  "CustomEvent",
  "Audio",
  "navigator",
] as const;
const originalGlobals = new Map(
  browserGlobalNames.map((name) => [
    name,
    Object.getOwnPropertyDescriptor(globalThis, name),
  ]),
);
const originalCreateObjectURL = URL.createObjectURL;
const originalRevokeObjectURL = URL.revokeObjectURL;

/**
 * The playback manager's invariants. The synthesis providers are exercised
 * elsewhere; what matters here is that the writer can never end up with two
 * editors talking at once, or with a voice they cannot stop.
 */

/** Minimal Audio + URL doubles: enough surface for the manager to drive. */
class FakeAudio {
  static instances: FakeAudio[] = [];
  src = "";
  currentTime = 0;
  duration = 0;
  muted = false;
  paused = true;
  playCount = 0;
  onended: (() => void) | null = null;
  onerror: (() => void) | null = null;
  ontimeupdate: (() => void) | null = null;
  onloadedmetadata: (() => void) | null = null;

  constructor() {
    FakeAudio.instances.push(this);
  }
  async play(): Promise<void> {
    this.paused = false;
    this.playCount += 1;
  }
  pause(): void {
    this.paused = true;
  }
}

let createdUrls = 0;
let revokedUrls = 0;
let speakModule: typeof import("./speech");

beforeEach(async () => {
  setBrowserTtsCapabilityOverride(undefined);
  Object.defineProperty(globalThis, "navigator", {
    configurable: true,
    value: { onLine: true },
  });
  FakeAudio.instances = [];
  createdUrls = 0;
  revokedUrls = 0;

  // The auth client takes its browser branch as soon as `window` exists, so
  // a stub `localStorage` has to come along with it.
  const storage = {
    getItem: () => null,
    setItem: () => {},
    removeItem: () => {},
    clear: () => {},
    key: () => null,
    length: 0,
  };
  Object.defineProperty(globalThis, "localStorage", {
    configurable: true,
    writable: true,
    value: storage,
  });
  Object.defineProperty(globalThis, "window", {
    configurable: true,
    value: {
      addEventListener: () => {},
      removeEventListener: () => {},
      dispatchEvent: () => true,
      localStorage: storage,
    },
  });
  const customEvent = class {
    type: string;
    detail: unknown;
    constructor(type: string, init?: { detail?: unknown }) {
      this.type = type;
      this.detail = init?.detail;
    }
  };
  for (const [name, value] of Object.entries({
    CustomEvent: customEvent,
    Audio: FakeAudio,
  }))
    Object.defineProperty(globalThis, name, {
      configurable: true,
      writable: true,
      value,
    });
  // Patch only the object-URL helpers — replacing the whole `URL` global
  // takes the constructor with it, which several dependencies rely on.
  URL.createObjectURL = () => `blob:fake-${++createdUrls}`;
  URL.revokeObjectURL = () => {
    revokedUrls += 1;
  };

  // Fresh module per test — the manager holds deliberate module-level state.
  speakModule = await import(`./speech?t=${Date.now()}${Math.random()}`);
});

afterEach(() => {
  setBrowserTtsCapabilityOverride(undefined);
  delete (globalThis as Record<string, unknown>).Audio;
});

afterAll(() => {
  for (const name of browserGlobalNames) {
    const descriptor = originalGlobals.get(name);
    if (descriptor) Object.defineProperty(globalThis, name, descriptor);
    else Reflect.deleteProperty(globalThis, name);
  }
  URL.createObjectURL = originalCreateObjectURL;
  URL.revokeObjectURL = originalRevokeObjectURL;
  releaseBrowserGlobalsLock();
});

describe("speechState", () => {
  test("a character comment starts with its own voice selected and named in the menu", async () => {
    const calls: Array<{ voice?: string }> = [];
    const client = {
      action: async (_ref: unknown, args: { voice?: string }) => {
        calls.push(args);
        return { audioBase64: "", mimeType: "audio/mpeg" };
      },
    } as never;
    await speakModule.speak({
      id: "lecteur-note",
      text: "I lost the thread here.",
      author: "Le Lecteur",
      client,
      signedIn: true,
    });
    const menu = await speakModule.currentSpeechVoiceMenu();
    expect(calls[0].voice).toBe("alloy");
    expect(menu?.selected).toBe("alloy");
    expect(menu?.options.find((option) => option.id === "alloy")?.label).toBe(
      "Le Lecteur",
    );
    expect(speakModule.speechState().label).toBe("Le Lecteur");
    await speakModule.restartSpeechWithVoice("onyx");
    expect((await speakModule.currentSpeechVoiceMenu())?.selected).toBe("onyx");
    await speakModule.speak({
      id: "lecteur-next",
      text: "And here too.",
      author: "Le Lecteur",
      client,
      signedIn: true,
    });
    expect((await speakModule.currentSpeechVoiceMenu())?.selected).toBe(
      "alloy",
    );
  });
  test("starts idle with nothing selected", () => {
    const s = speakModule.speechState();
    expect(s.status).toBe("idle");
    expect(s.id).toBeNull();
    expect(s.error).toBeNull();
  });

  test("returns a copy, so a caller cannot mutate the manager's state", () => {
    const a = speakModule.speechState();
    a.status = "playing";
    expect(speakModule.speechState().status).toBe("idle");
  });
});

describe("stopSpeech", () => {
  test("is safe when nothing is playing", () => {
    expect(() => speakModule.stopSpeech()).not.toThrow();
    expect(speakModule.speechState().status).toBe("idle");
  });

  test("returns to idle with no active id", () => {
    speakModule.stopSpeech();
    const s = speakModule.speechState();
    expect(s.status).toBe("idle");
    expect(s.id).toBeNull();
  });
});

describe("speak", () => {
  test("hosted synthesis sends the resolved saved voice shown by the picker", async () => {
    const settings = aiClient.normalizeAiSettings(null);
    settings.perFeature["voice-narration"] = { voice: "shimmer" };
    const cached = spyOn(orchestrator, "getCachedAiSettings").mockResolvedValue(
      settings,
    );
    const voices: Array<string | undefined> = [];
    const client = {
      action: async (_ref: unknown, args: { voice?: string }) => {
        voices.push(args.voice);
        return { audioBase64: "", mimeType: "audio/mpeg" };
      },
    } as never;
    try {
      await speakModule.speak({
        id: "saved-hosted-voice",
        text: "A fictional passage.",
        client,
        signedIn: true,
      });
      expect(voices).toEqual(["shimmer"]);
      expect((await speakModule.currentSpeechVoiceMenu())?.selected).toBe(
        "shimmer",
      );
      await speakModule.restartSpeechWithVoice("cedar");
      expect(voices).toEqual(["shimmer", "cedar"]);
      expect((await speakModule.currentSpeechVoiceMenu())?.selected).toBe(
        "cedar",
      );
    } finally {
      cached.mockRestore();
    }
  });
  for (const scenario of [
    { signedIn: true, online: true, hosted: true },
    { signedIn: true, online: false, hosted: false },
    { signedIn: false, online: true, hosted: false },
  ]) {
    test(`automatic browser voice: signedIn=${scenario.signedIn}, online=${scenario.online} uses ${scenario.hosted ? "hosted" : "local"} narration`, async () => {
      setBrowserTtsCapabilityOverride("wasm");
      Object.defineProperty(globalThis, "navigator", {
        configurable: true,
        value: { onLine: scenario.online },
      });
      const settings = aiClient.normalizeAiSettings(null);
      const cached = spyOn(
        orchestrator,
        "getCachedAiSettings",
      ).mockResolvedValue(settings);

