export async function speakQueue(
  requests: SpeakRequest[],
  options: { startIndex?: number; ownerId?: string } = {},
): Promise<void> {
  if (typeof window === "undefined") return;

  const items = requests.filter((r) => r.text.trim());
  if (!items.length) return;

