import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/@playwright/test/index.mjs";
import { writeFile } from "node:fs/promises";

const browser = await chromium.launch({ args: ["--autoplay-policy=no-user-gesture-required"] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on("pageerror", (error) => errors.push(error.message));
try {
  await page.goto("http://localhost:5173/desk/");
  await page.getByRole("heading", { name: "My Desk", exact: true }).waitFor();
  await page.waitForFunction(() => performance.getEntriesByType("resource").some((entry) => new URL(entry.name).pathname === "/src/utils/speech.ts"));
  const decoded = await page.evaluate(async () => {
    const moduleUrl = performance.getEntriesByType("resource").find((entry) => new URL(entry.name).pathname === "/src/utils/speech.ts").name;
    window.recordedSpeechModuleUrl = moduleUrl;
    const response = await fetch("http://localhost:5193/Alice.response.json").then((result) => result.json());
    const text = "The light remained on until the last page was finished.";
    const article = document.createElement("article");
    article.style.cssText = "padding:24px;margin:20px 0;max-width:60rem;font:28px/1.8 var(--font-serif);";
    const heading = document.createElement("h2");
    heading.textContent = "Recorded ElevenLabs narration";
    heading.style.cssText = "font:18px var(--font-sans);margin-bottom:16px";
    const prose = document.createElement("p");
    prose.dataset.speechId = "recorded-elevenlabs-proof";
    prose.dataset.speechSource = "plain";
    prose.textContent = text;
    article.append(heading, prose);
    document.querySelector("main").prepend(article);
    const NativeAudio = window.Audio;
    window.Audio = function (...args) {
      const audio = new NativeAudio(...args);
      window.recordedSpeechAudio = audio;
      return audio;
    };
    const bytes = Uint8Array.from(atob(response.audioBase64), (character) => character.charCodeAt(0));
    const context = new AudioContext();
    const buffer = await context.decodeAudioData(bytes.buffer.slice(0));
    const samples = buffer.getChannelData(0);
    let peak = 0;
    let sum = 0;
    for (const sample of samples) { peak = Math.max(peak, Math.abs(sample)); sum += sample * sample; }
    await context.close();
    const speech = await import(moduleUrl);
    await speech.speak({ id: "recorded-elevenlabs-proof", text, voice: "Alice", signedIn: true, client: { action: async () => response } });
    return { byteLength: bytes.byteLength, frames: buffer.length, sampleRate: buffer.sampleRate, decodedDuration: buffer.duration, peak, rms: Math.sqrt(sum / samples.length), alignedWords: response.alignment.ranges.length };
  });
