    const range = Array.from(CSS.highlights.get("twyne-speech-word") ?? [])[0];
    return range?.toString() === "remained" && window.recordedSpeechAudio.currentTime >= 0.48;
  }, { timeout: 7000 });
  await page.getByRole("button", { name: "Pause narration", exact: true }).click();
  const paused = await page.evaluate(async () => {
    const speech = await import(window.recordedSpeechModuleUrl);
    return { status: speech.speechState().status, audioTime: window.recordedSpeechAudio.currentTime, nativePaused: window.recordedSpeechAudio.paused, highlighted: Array.from(CSS.highlights.get("twyne-speech-word") ?? [])[0]?.toString(), readyState: window.recordedSpeechAudio.readyState, duration: window.recordedSpeechAudio.duration };
